(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.MartinsFluxos=api;})(globalThis,()=>{'use strict';
function iso(raw){const s=String(raw||'').trim(),m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/),v=m?m[3]+'-'+m[2]+'-'+m[1]:s;if(!/^\d{4}-\d{2}-\d{2}$/.test(v)||v.startsWith('0000-'))throw Error('Informe data válida no padrão dd/mm/aaaa');const d=new Date(v+'T12:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)throw Error('Data inválida');return v;}
function br(raw){if(!raw)return '';const v=iso(raw);return v.slice(8)+'/'+v.slice(5,7)+'/'+v.slice(0,4);}
function dates(raw){const list=String(raw||'').split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean).map(iso);if(!list.length||list.length>31)throw Error('Informe de 1 a 31 datas de destino');return [...new Set(list)];}
const fold=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function auditOptions(logs,users,modules=[]){const people=new Map();for(const u of users)if(u&&u.nome)people.set('login:'+(u.usuario||u.email||u.id),{key:'login:'+(u.usuario||u.email||u.id),name:u.nome,login:String(u.usuario||u.email||u.id)});for(const l of logs){const login=String(l.usuario||l.login||''),name=String(l.nomeUsuario||l.nome||login||'Usuário não informado'),key=login?'login:'+login:'name:'+name;if(!people.has(key))people.set(key,{key,name,login});}return {users:[...people.values()].sort((a,b)=>a.name.localeCompare(b.name)),modules:[...new Set([...modules,...logs.map(l=>String(l.modulo||'Não informado'))])].sort((a,b)=>a.localeCompare(b))};}
function filterLogs(logs,{user='todos',userName='',module='todos',text='',start='',end=''}={}){const terms=fold(text).split(/\s+/).filter(Boolean);return logs.filter(l=>{const login=String(l.usuario||l.login||''),name=String(l.nomeUsuario||l.nome||login||'Usuário não informado');if(user!=='todos'&&(user.startsWith('login:')?login!==user.slice(6)&&!( !login&&(name===userName||name===user.slice(6))):user.startsWith('name:')?name!==user.slice(5):name!==user))return false;if(module!=='todos'&&String(l.modulo||'Não informado')!==module)return false;let day;try{day=iso(l.data);}catch{day='';}if((start&&(!day||day<start))||(end&&(!day||day>end)))return false;const hay=fold([l.acao,name,login,l.modulo,l.obra,l.funcionario,l.perfil].join(' '));return terms.every(t=>hay.includes(t));});}
function saveClient(rows,input,id,newId){const nome=String(input.nome||'').trim();if(!nome)throw Error('Informe o nome do cliente');const next=structuredClone(rows);if(id&&next.filter(x=>x.id===id).length!==1)throw Error('Cliente alterado ou removido; atualize o cadastro');if(next.some(x=>x.id!==id&&fold(x.nome.trim())===fold(nome)))throw Error('Nome já cadastrado; selecione e edite o cliente existente');const values={nome,doc:String(input.doc||'').trim(),tel:String(input.tel||'').trim(),cidade:String(input.cidade||'').trim(),obs:String(input.obs||'').trim()};let client;if(id){const i=next.findIndex(x=>x.id===id);client=next[i]={...next[i],...values};}else{client={id:newId,...values};next.unshift(client);}return {rows:next,client};}
return {iso,br,dates,fold,auditOptions,filterLogs,saveClient};});
